// server/llm.js). Falls back to a graceful error message if the endpoint
// is unreachable. Persists the conversation to localStorage.
const messages = [];
const STORAGE_KEY = 'cs.ai.messages';
try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'); if (Array.isArray(saved)) saved.forEach(function (m){ if (m && m.role && m.text) messages.push(m); }); } catch (_) {}

function save() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(messages.slice(-50))); } catch (_) {} }

