// (data/kb.json). The \`score\` function is a hot-swap point — in production
// replace it with vector similarity (OpenAI embeddings, sentence-transformers,
// or a local model). The export interface is identical.
const fs = require('fs');
const path = require('path');

const KB_PATH = process.env.RAG_KB_PATH || path.join(process.cwd(), 'data', 'kb.json');
let KB = [];
let KB_LOADED = false;

function load() {
  try {
    KB = JSON.parse(fs.readFileSync(KB_PATH, 'utf8'));
    if (!Array.isArray(KB)) KB = [];
  } catch (_) { KB = []; }
  KB_LOADED = true;
}
function tokens(s) {
  return String(s || '').toLowerCase()
    .replace(/[^a-z0-9\\\\s]/g, ' ')
    .split(/\\\\s+/)
    .filter(Boolean);
}
function score(query, doc) {
  const q = new Set(tokens(query));
  const t = tokens((doc.title || '') + ' ' + (doc.body || ''));
  if (!q.size || !t.length) return 0;
  const tf = {};
  for (const x of t) tf[x] = (tf[x] || 0) + 1;
  let s = 0;
  q.forEach(function (x) { if (tf[x]) s += Math.log(1 + tf[x]); });
  return s / Math.sqrt(t.length);
}
module.exports = async function rag(query, k) {
  k = k || 4;
  if (!KB_LOADED) load();
  return {
    context: KB
      .map(function (d) { return { d: d, s: score(query, d) }; })
      .sort(function (a, b) { return b.s - a.s; })
      .slice(0, k)
      .filter(function (x) { return x.s > 0; })
      .map(function (x) { return (x.d.title || '') + ': ' + (x.d.body || ''); })
      .join('\\\\n\\\\n')
  };
};
